# hypothesis: an __exit__ annotated as returning Literal[False] tells checkers the block cannot swallow, yet the method returns True, so a name bound after a raising statement keeps its pre-block value at runtime; generator and suppress controls behave as annotated.
from collections.abc import Iterator
from contextlib import contextmanager, suppress
from typing import Literal, reveal_type


class Flipped:
    def __enter__(self) -> int:
        return 1

    def __exit__(self, *args: object) -> Literal[False]:
        return True


@contextmanager
def guarded_gen() -> Iterator[None]:
    yield


def flipped_block(fail: bool) -> int | None:
    x: int | None = None
    with Flipped():
        if fail:
            raise ValueError('boom')
        x = 1
    print('after flipped block ran')
    reveal_type(x)
    return x


def generator_block(fail: bool) -> int | None:
    z: int | None = None
    with guarded_gen():
        if fail:
            raise ValueError('gen')
        z = 2
    return z


def suppress_block(fail: bool) -> int | None:
    w: int | None = None
    with suppress(ValueError):
        if fail:
            raise ValueError('sup')
        w = 3
    return w


print(flipped_block(False))
print(flipped_block(True))
print(suppress_block(False), suppress_block(True))
try:
    print(generator_block(True))
except ValueError as exc:
    print('generator re-raised:', exc)
print(generator_block(False))
